# Seed tool: multi-engine web search (all / baidu / sogou / ddg).
# ponytail: baidu/sogou 返回跳转链接不展开；解析选择器随站点改版会失效，Agent 可自更新本脚本。
import json
import urllib.parse
from concurrent.futures import ThreadPoolExecutor

import requests
from bs4 import BeautifulSoup

_UA_ANDROID = "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36"
_UA_DESKTOP = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"


def main(query: str, engine: str = "all", max_results: int = 8):
    '''Search the web. engine: "all" (default, merges Baidu + Sogou + DuckDuckGo), "baidu", "sogou" or "ddg". Returns a list of {title, url, snippet}.'''
    engines = ("baidu", "sogou", "ddg") if engine == "all" else (engine,)
    with ThreadPoolExecutor(max_workers=len(engines)) as pool:
        futures = [pool.submit(_search, e, query, max_results) for e in engines]
        # ddg 在无代理网络会超时，给短 timeout 快速失败，不拖慢整体
        fetched = []
        for e, fut in zip(engines, futures):
            try:
                fetched.append(fut.result(timeout=20))
            except Exception:
                fetched.append([])
    print(json.dumps(_merge(fetched, max_results), ensure_ascii=False))


def _search(engine: str, query: str, max_results: int):
    if engine == "baidu":
        # baidu 桌面 UA 会触发验证码，必须移动 UA
        resp = requests.get(
            "https://www.baidu.com/s",
            params={"wd": query},
            headers={"User-Agent": _UA_ANDROID},
            timeout=15,
        )
        parser = _parse_baidu
    elif engine == "sogou":
        resp = requests.get(
            "https://www.sogou.com/web",
            params={"query": query},
            headers={"User-Agent": _UA_DESKTOP},
            timeout=15,
        )
        parser = _parse_sogou
    else:
        resp = requests.post(
            "https://html.duckduckgo.com/html/",
            data={"q": query},
            headers={"User-Agent": _UA_ANDROID},
            timeout=8,
        )
        parser = _parse_ddg
    resp.raise_for_status()
    soup = BeautifulSoup(resp.text, "html.parser")
    return parser(soup, max_results)


def _merge(lists, max_results):
    seen = set()
    merged = []
    for group in lists:
        for item in group:
            url = item.get("url", "")
            if url in seen:
                continue
            seen.add(url)
            merged.append(item)
            if len(merged) >= max_results:
                return merged
    return merged


def _parse_ddg(soup, max_results):
    results = []
    for item in soup.select("div.result.results_links")[: max_results]:
        link = item.select_one("a.result__a")
        if link is None:
            continue
        snippet_el = item.select_one("td.result__snippet") or item.select_one(".result__snippet")
        _append(results, link.get_text(strip=True), _clean_ddg_url(link.get("href", "")), snippet_el)
        if len(results) >= max_results:
            break
    return results


def _parse_baidu(soup, max_results):
    results = []
    for item in soup.select("div.c-result"):
        if len(results) >= max_results:
            break
        title_el = item.select_one("h3")
        if title_el is None:
            continue
        try:
            url = json.loads(item.get("data-log", "{}")).get("mu", "")
        except ValueError:
            url = ""
        snippet_el = None
        for sel in ("[class*=content-right]", "[class*=abstract]", "[class*=clamp]", "[class*=desc]"):
            candidate = item.select_one(sel)
            if candidate is not None:
                snippet_el = candidate
                break
        _append(results, title_el.get_text(strip=True), url, snippet_el)
    return results


def _parse_sogou(soup, max_results):
    results = []
    for item in soup.select("div.vrwrap, div.rb"):
        if len(results) >= max_results:
            break
        link = item.select_one("h3 a")
        if link is None:
            continue
        snippet_el = item.select_one(".str-text-info") or item.select_one(".str_info") or item.select_one(".space-txt")
        _append(results, link.get_text(strip=True), _clean_sogou_url(link.get("href", "")), snippet_el)
    return results


def _append(results, title, url, snippet_el):
    snippet = snippet_el.get_text(strip=True) if snippet_el else ""
    if title and url:
        results.append({"title": title, "url": url, "snippet": snippet})


def _clean_ddg_url(href: str) -> str:
    if href.startswith("//duckduckgo.com/l/") or href.startswith("https://duckduckgo.com/l/"):
        parsed = urllib.parse.urlparse(href if href.startswith("http") else "https:" + href)
        target = urllib.parse.parse_qs(parsed.query).get("uddg", [""])[0]
        return urllib.parse.unquote(target)
    return href


def _clean_sogou_url(href: str) -> str:
    if href.startswith("/link"):
        return "https://www.sogou.com" + href
    return href

# Seed tool: fetch a URL and extract readable article text (companion to py_web_search,
# use when search only gives snippets and the full page is needed).
# ponytail: article-container selectors break on site redesigns; Agent can self-update this script.
import re
import html
import requests


def _clean(s: str) -> str:
    s = re.sub(r'[ \t\u00a0\u3000]+', ' ', s)
    s = re.sub(r'\n\s*\n+', '\n', s)
    return '\n'.join(line.strip() for line in s.split('\n') if line.strip())


def _extract_article(raw: str) -> str:
    # 1) <article> block
    m = re.search(r'<article\b[\s\S]*?</article>', raw, re.I)
    if m:
        return m.group(0)

    # 2) common article container div, depth-aware closing match
    m = re.search(
        r'<div\b[^>]*(?:art_content|artibody|article-content|article_content|article|content)[^>]*>',
        raw, re.I,
    )
    if m:
        start = m.start()
        depth = 0
        i = start
        while i < len(raw):
            op = re.match(r'<div\b[^>]*>', raw[i:], re.I)
            cl = re.match(r'</div\s*>', raw[i:], re.I)
            if cl:
                depth -= 1
                if depth <= 0:
                    return raw[start:i + cl.end()]
                i += cl.end()
                continue
            if op:
                tag = op.group(0)
                if not tag.rstrip().endswith('/>'):
                    depth += 1
                i += op.end()
                continue
            i += 1
        return raw[start:]

    # 3) <body> fallback
    m = re.search(r'<body\b[\s\S]*?</body>', raw, re.I)
    if m:
        return m.group(0)

    return raw


def _decoded_text(r) -> str:
    enc = None
    m = re.search(r'charset=["\']?([\w-]+)', r.headers.get('Content-Type', ''), re.I)
    if m:
        enc = m.group(1)
    if not enc:
        m = re.search(r'<meta[^>]+charset=["\']?([\w-]+)', r.text[:2000], re.I)
        if m:
            enc = m.group(1)
    candidates = [enc, 'utf-8', 'gb18030']
    for c in candidates:
        if not c:
            continue
        try:
            r.encoding = c
            return r.text
        except Exception:
            continue
    return r.text


def main(url: str, keyword: str = "", max_chars: int = 6000, timeout: int = 25):
    """抓取网页并提取可读正文。可选 keyword：只返回关键词附近的一整段文本（定位到后前后各取一半 max_chars）。
    当 py_web_search 只给摘要、需要读全文时使用。"""
    headers = {
        'User-Agent': 'Mozilla/5.0 (Linux; Android 12; Pixel 6) AppleWebKit/537.36 '
                      '(KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
    }
    r = requests.get(url, headers=headers, timeout=timeout)
    r.raise_for_status()
    raw = _decoded_text(r)

    # strip noisy blocks
    raw = re.sub(r'<(script|style|noscript|iframe|svg)[\s\S]*?</\1>', ' ', raw, flags=re.I)
    raw = re.sub(r'<head[\s\S]*?</head>', ' ', raw, flags=re.I)

    body = _extract_article(raw)
    body = re.sub(r'<(script|style|noscript)[\s\S]*?</\1>', ' ', body, flags=re.I)

    text = re.sub(r'<[^>]+>', '\n', body)
    text = html.unescape(text)
    text = _clean(text)

    if keyword:
        idx = text.lower().find(keyword.lower())
        if idx >= 0:
            start = max(0, idx - max_chars // 2)
            text = text[start:start + max_chars]
        else:
            text = text[:max_chars]
    else:
        text = text[:max_chars]

    print(text)

import shlex
import subprocess
import sys


def su_run(args, timeout=15):
    """在 root 下执行命令；找不到 su 时抛 FileNotFoundError。"""
    cmd = ["su", "-c", " ".join(shlex.quote(a) for a in args)]
    return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)


def main():
    '''启动微信 (Launch WeChat).'''
    # 非 root 直接 am start 会 SecurityException: Permission Denied；经 su 执行，
    # 首次调用会弹出 su 授权对话框，同意后启动。
    try:
        result = su_run(["am", "start", "-n", "com.tencent.mm/com.tencent.mm.ui.LauncherUI"])
    except FileNotFoundError:
        print("未找到 su：需要 root（Magisk / KernelSU 授权后重试）", file=sys.stderr)
        raise SystemExit(2)
    if result.returncode != 0:
        print((result.stderr or result.stdout).strip())
        raise SystemExit(1)
    print("WeChat launched.")

"""Places and routes: where is X, how far, how long, opening hours.

Sources, on purpose:
  * SerpApi engine=google_maps to find businesses (rating, address, hours) - token at
    files/tool_output/serpapi/.token.
  * Nominatim (OSM) for plain geocoding of addresses and landmarks - free, no key.
  * Google Routes API v2 for travel time: the legacy Directions API is not enabled on this
    project, so files/google_maps_key.txt only works against the new endpoints.
"""
import os
import time

FILES = "/data/user/0/com.niki914.zafiro.evergrow.debug/files"
SERP = FILES + "/tool_output/serpapi/.token"
GMAPS = FILES + "/google_maps_key.txt"
TRAVEL = {"drive": "DRIVE", "walk": "WALK", "transit": "TRANSIT", "bike": "BICYCLE"}
UA = {"User-Agent": "EvergrowAgent/1.0 (personal phone assistant)"}


def _read(path):
    if not os.path.exists(path):
        return ""
    with open(path) as f:
        return f.read().strip()


def _serp_place(query, near=""):
    import requests

    token = _read(SERP)
    if not token:
        return None, "serpapi token missing (run py_restore_keys)"
    params = {"engine": "google_maps", "q": query, "hl": "en", "gl": "hk", "api_key": token}
    if near:
        params["ll"] = near
    t0 = time.time()
    hits = requests.get("https://serpapi.com/search", params=params, timeout=30).json().get("local_results") or []
    if not hits:
        return None, "no business match for %r" % query
    b = hits[0]
    g = b.get("gps_coordinates") or {}
    return {"title": b.get("title"), "address": b.get("address"), "rating": b.get("rating"),
            "reviews": b.get("reviews"), "hours": b.get("hours") or b.get("open_state"),
            "lat": g.get("latitude"), "lng": g.get("longitude"),
            "latency": round(time.time() - t0, 2)}, None


def _geocode(query):
    import requests

    t0 = time.time()
    try:
        r = requests.get("https://nominatim.openstreetmap.org/search",
                         params={"q": query, "format": "json", "limit": 1}, headers=UA, timeout=25)
        hits = r.json()
        if hits:
            h = hits[0]
            return (float(h["lat"]), float(h["lon"])), h.get("display_name"), round(time.time() - t0, 2)
    except Exception as e:
        return None, "%s: %s" % (type(e).__name__, str(e)[:80]), round(time.time() - t0, 2)
    return None, "Nominatim found nothing", round(time.time() - t0, 2)


def _coords(value, near=""):
    if "," in value:
        a, b = value.split(",")[:2]
        try:
            return (float(a), float(b)), value, None
        except ValueError:
            pass
    place, err = _serp_place(value, near)
    if place and place["lat"] is not None:
        return (place["lat"], place["lng"]), place.get("address") or value, None
    coords, label, secs = _geocode(value)
    if coords:
        return coords, label, None
    return None, None, "could not locate %r (%s)" % (value, label)


def _route(o, d, mode="transit"):
    import requests

    key = _read(GMAPS)
    if not key:
        return None, "google maps key missing (run py_restore_keys)"
    body = {"origin": {"location": {"latLng": {"latitude": o[0], "longitude": o[1]}}},
            "destination": {"location": {"latLng": {"latitude": d[0], "longitude": d[1]}}},
            "travelMode": TRAVEL.get(mode, "TRANSIT")}
    t0 = time.time()
    r = requests.post("https://routes.googleapis.com/directions/v2:computeRoutes",
                      headers={"X-Goog-Api-Key": key,
                               "X-Goog-FieldMask": "routes.duration,routes.distanceMeters"}, json=body, timeout=30)
    if r.status_code != 200:
        return None, "Routes API HTTP %d: %s" % (r.status_code, r.text[:150])
    routes = r.json().get("routes") or []
    if not routes:
        return None, "no %s route found" % mode
    rt = routes[0]
    return {"km": round(rt.get("distanceMeters", 0) / 1000, 2),
            "min": round(int(str(rt.get("duration", "0s")).rstrip("s")) / 60),
            "latency": round(time.time() - t0, 2)}, None


def main(query: str = "", destination: str = "", origin: str = "", mode: str = "transit", near: str = "") -> str:
    """Find a place, or get travel time between two places. mode: drive/walk/transit/bike."""
    if origin and destination:
        o, olabel, err = _coords(origin, near)
        if err:
            print(err)
            return err
        d, dlabel, err = _coords(destination, near)
        if err:
            print(err)
            return err
        route, err = _route(o, d, mode)
        if err:
            print(err)
            return err
        out = "%s -> %s: %.1f km, about %d min by %s (Routes API %.1fs)" % (
            olabel, dlabel, route["km"], route["min"], mode, route["latency"])
        print(out)
        return out
    if not query:
        out = "give query= for a place, or origin= and destination= for a route"
        print(out)
        return out
    place, err = _serp_place(query, near)
    if err:
        coords, label, secs = _geocode(query)
        if not coords:
            print(err)
            return err
        out = "%s | %s | %.4f,%.4f (Nominatim %.1fs)" % (query, label, coords[0], coords[1], secs)
        print(out)
        return out
    bits = [place["title"] or query]
    if place["rating"] is not None:
        bits.append("%s stars" % place["rating"] + (" from %s reviews" % place["reviews"] if place["reviews"] else ""))
    for k in ("address", "hours"):
        if place[k]:
            bits.append(str(place[k]))
    if place["lat"] is not None:
        bits.append("%.4f,%.4f" % (place["lat"], place["lng"]))
    out = " | ".join(bits) + " (SerpApi %.1fs)" % place["latency"]
    print(out)
    return out
